// Example solution descriptions and code
const solutionData = {
  1: {
    description: "The 'Two Sum' problem asks us to find two numbers in an array that add up to a specific target. We'll return the indices of these two numbers.",
    examples: [
      {
        input: "nums = [2, 7, 11, 15], target = 9",
        output: "[0, 1]",
        explanation: "Because nums[0] + nums[1] = 2 + 7 = 9, we return [0, 1]."
      },
      {
        input: "nums = [3, 2, 4], target = 6",
        output: "[1, 2]",
        explanation: "Because nums[1] + nums[2] = 2 + 4 = 6, we return [1, 2]."
      },
      {
        input: "nums = [3, 3], target = 6",
        output: "[0, 1]",
        explanation: "Because nums[0] + nums[1] = 3 + 3 = 6, we return [0, 1]."
      }
    ],
    approach: "We can use a hash map to solve this problem efficiently. As we iterate through the array, for each element we check if the target minus the current element exists in the hash map. If it does, we've found our solution. If not, we add the current element to the hash map and continue.",
    timeComplexity: "O(n) where n is the length of the array.",
    spaceComplexity: "O(n) for storing elements in the hash map.",
    code: {
      java: `public int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> map = new HashMap<>();
    
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        
        if (map.containsKey(complement)) {
            return new int[] { map.get(complement), i };
        }
        
        map.put(nums[i], i);
    }
    
    return null; // No solution found
}`
    }
  },
  2: {
    description: "You are given two non-empty linked lists representing two non-negative integers. The digits are stored in reverse order, and each of their nodes contains a single digit. Add the two numbers and return the sum as a linked list. You may assume the two numbers do not contain any leading zero, except the number 0 itself.",
    examples: [
      {
        input: "l1 = [2,4,3], l2 = [5,6,4]",
        output: "[7,0,8]",
        explanation: "342 + 465 = 807."
      },
      {
        input: "l1 = [0], l2 = [0]",
        output: "[0]",
        explanation: "0 + 0 = 0."
      },
      {
        input: "l1 = [9,9,9,9,9,9,9], l2 = [9,9,9,9]",
        output: "[8,9,9,9,0,0,0,1]",
        explanation: "9999999 + 9999 = 10009998."
      }
    ],
    approach: "We traverse both linked lists simultaneously, adding corresponding digits along with any carry from the previous addition. If one list is longer than the other, we continue traversing the longer list. If there's a final carry after all nodes are processed, we add a new node with the carry value.",
    timeComplexity: "O(max(m, n)) where m and n are lengths of the two linked lists.",
    spaceComplexity: "O(max(m, n)) for the result linked list, not counting the input storage.",
    code: {
      java: `/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
    // Create a dummy head node
    ListNode dummyHead = new ListNode(0);
    ListNode current = dummyHead;
    
    int carry = 0;
    ListNode p = l1, q = l2;
    
    // Process both lists while at least one is not empty
    while (p != null || q != null) {
        // Get the values of current nodes or 0 if the node is null
        int x = (p != null) ? p.val : 0;
        int y = (q != null) ? q.val : 0;
        
        // Calculate sum and new carry
        int sum = x + y + carry;
        carry = sum / 10;
        
        // Create a new node with the digit value and move current pointer
        current.next = new ListNode(sum % 10);
        current = current.next;
        
        // Move to next nodes in both lists if available
        if (p != null) p = p.next;
        if (q != null) q = q.next;
    }
    
    // If there's still a carry, create a new node
    if (carry > 0) {
        current.next = new ListNode(carry);
    }
    
    // Return the result list (skip the dummy head)
    return dummyHead.next;
}`
    }
  },
  3: {
    description: "Given a string, find the length of the longest substring without repeating characters.",
    examples: [
      {
        input: "s = \"abcabcbb\"",
        output: "3",
        explanation: "The longest substring without repeating characters is \"abc\", with length 3."
      },
      {
        input: "s = \"bbbbb\"",
        output: "1",
        explanation: "The longest substring without repeating characters is \"b\", with length 1."
      },
      {
        input: "s = \"pwwkew\"",
        output: "3",
        explanation: "The longest substring without repeating characters is \"wke\", with length 3. Note that the answer must be a substring, \"pwke\" is a subsequence and not a substring."
      }
    ],
    approach: "We can use a sliding window technique combined with a hash set to solve this problem efficiently. We maintain a sliding window with a left and right pointer, and a set to track characters in the current window. We expand the window by moving the right pointer and add characters to the set. When we encounter a duplicate, we contract the window from the left until the duplicate is removed, then continue expanding.",
    timeComplexity: "O(n) where n is the length of the string. We process each character at most twice (once when adding to the window and once when removing).",
    spaceComplexity: "O(min(m, n)) where n is the length of the string and m is the size of the character set. The space needed depends on the number of unique characters.",
    code: {
      java: `public int lengthOfLongestSubstring(String s) {
    // Set to keep track of characters in current window
    Set<Character> charSet = new HashSet<>();
    int maxLength = 0;
    int left = 0;
    
    // Iterate through the string with right pointer
    for (int right = 0; right < s.length(); right++) {
        // If character already in set, remove characters from left
        // until we remove the duplicate
        while (charSet.contains(s.charAt(right))) {
            charSet.remove(s.charAt(left));
            left++;
        }
        
        // Add current character to set
        charSet.add(s.charAt(right));
        
        // Update max length if current window is larger
        maxLength = Math.max(maxLength, right - left + 1);
    }
    
    return maxLength;
}`
    }
  },
  20: {
    description: "Given a string containing just the characters '(', ')', '{', '}', '[' and ']', determine if the input string is valid. A string is valid if: 1) Open brackets must be closed by the same type of brackets. 2) Open brackets must be closed in the correct order. 3) Every close bracket has a corresponding open bracket of the same type.",
    examples: [
      {
        input: "s = \"()\"",
        output: "true",
        explanation: "The input string contains one pair of parentheses, which are properly matched."
      },
      {
        input: "s = \"()[]{}\"",
        output: "true",
        explanation: "The input string contains three pairs of parentheses, all of which are properly matched."
      },
      {
        input: "s = \"(]\"",
        output: "false",
        explanation: "The input string contains a mismatched pair of parentheses, an opening '(' and a closing ']'."
      },
      {
        input: "s = \"([)]\"",
        output: "false",
        explanation: "The brackets must be closed in the correct order, meaning '(' must be closed before '['."
      }
    ],
    approach: "We can use a stack data structure to solve this problem. We iterate through the string, pushing opening brackets onto the stack. When we encounter a closing bracket, we check if it matches the most recent opening bracket on the stack. If it does, we pop the opening bracket off the stack and continue. If not, the string is invalid. At the end, the stack should be empty for a valid string.",
    timeComplexity: "O(n) where n is the length of the string. We iterate through each character exactly once.",
    spaceComplexity: "O(n) in the worst case if the string contains only opening brackets, the stack would store all of them.",
    code: {
      java: `public boolean isValid(String s) {
    // Map to store the matching bracket pairs
    Map<Character, Character> bracketMap = new HashMap<>();
    bracketMap.put('(', ')');
    bracketMap.put('{', '}');
    bracketMap.put('[', ']');
    
    // Stack to keep track of opening brackets
    Stack<Character> stack = new Stack<>();
    
    // Iterate through the characters in the string
    for (char c : s.toCharArray()) {
        // If it's an opening bracket, push it to the stack
        if (bracketMap.containsKey(c)) {
            stack.push(c);
        } else {
            // It's a closing bracket
            // Return false if stack is empty (no matching opening bracket)
            if (stack.isEmpty()) {
                return false;
            }
            
            // Get the last opening bracket from the stack
            char lastBracket = stack.pop();
            
            // Check if the current closing bracket matches the last opening bracket
            if (bracketMap.get(lastBracket) != c) {
                return false;
            }
        }
    }
    
    // The string is valid if the stack is empty
    return stack.isEmpty();
}`
    }
  },
  21: {
    description: "You are given the heads of two sorted linked lists list1 and list2. Merge the two lists into one sorted list. The list should be made by splicing together the nodes of the first two lists, and return the head of the merged linked list.",
    examples: [
      {
        input: "list1 = [1,2,4], list2 = [1,3,4]",
        output: "[1,1,2,3,4,4]",
        explanation: "The two lists are merged by comparing values at each position and taking the smaller one."
      },
      {
        input: "list1 = [], list2 = []",
        output: "[]",
        explanation: "Both lists are empty, so the result is an empty list."
      },
      {
        input: "list1 = [], list2 = [0]",
        output: "[0]",
        explanation: "The first list is empty, so we return the second list."
      }
    ],
    approach: "We can solve this problem by using a dummy head node to simplify edge cases. We'll maintain a tail pointer to track the last node of our result list. At each step, we compare the values of the current nodes from both lists and append the smaller value to our result list. We continue this process until we've processed all nodes from both lists.",
    timeComplexity: "O(n + m) where n and m are the lengths of the two input lists.",
    spaceComplexity: "O(1) as we're reusing the existing nodes and only creating one dummy node.",
    code: {
      java: `/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        // Create a dummy head to simplify edge cases
        ListNode dummy = new ListNode(-1);
        ListNode tail = dummy;
        
        // Traverse both lists and compare values
        while (list1 != null && list2 != null) {
            if (list1.val <= list2.val) {
                tail.next = list1;
                list1 = list1.next;
            } else {
                tail.next = list2;
                list2 = list2.next;
            }
            tail = tail.next;
        }
        
        // Attach any remaining nodes
        if (list1 != null) {
            tail.next = list1;
        } else {
            tail.next = list2;
        }
        
        return dummy.next;
    }
}`
    }
  }
};

const InterviewQuestionDetailPage = () => {
  const { questionId } = useParams();
  const navigate = useNavigate();
  const [question, setQuestion] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState('description');
  
  useEffect(() => {
    // Find the question by ID
    const foundQuestion = questions.find(q => q.id === parseInt(questionId));
    
    if (foundQuestion) {
      setQuestion(foundQuestion);
      setLoading(false);
    } else {
      setError('Question not found');
      setLoading(false);
    }
  }, [questionId]);
  
  useEffect(() => {
    // Highlight code when tab changes
    if (activeTab === 'solution' && Prism) {
      Prism.highlightAll();
    }
  }, [activeTab]);
  
  const handleBack = () => {
    navigate('/interview-questions');
  };
  
  if (loading) {
    return (
      <PageContainer>
        <LoadingState>Loading question details...</LoadingState>
      </PageContainer>
    );
  }
  
  if (error) {
    return (
      <PageContainer>
        <ErrorState>{error}</ErrorState>
        <BackButton onClick={handleBack}>← Back to Questions</BackButton>
      </PageContainer>
    );
  }
  
  // Get solution data if available, otherwise use placeholder
  const solution = solutionData[question.id] || {
    description: "Detailed solution for this problem is coming soon.",
    examples: [],
    approach: "Solution approach will be added soon.",
    timeComplexity: "To be determined",
    spaceComplexity: "To be determined",
    code: {
      java: "// Solution code will be added soon"
    }
  };
  
  // Get visualization component based on question ID
  const getVisualizationComponent = (id) => {
    switch (parseInt(id)) {
      case 1:
        return (
          <Suspense fallback={<div>Loading visualization...</div>}>
            <TwoSumVisualization />
          </Suspense>
        );
      case 2:
        return (
          <Suspense fallback={<div>Loading visualization...</div>}>
            <AddTwoNumbersVisualization />
          </Suspense>
        );
      case 3:
        return (
          <Suspense fallback={<div>Loading visualization...</div>}>
            <LongestSubstringVisualization />
          </Suspense>
        );
      case 20:
        return (
          <Suspense fallback={<div>Loading visualization...</div>}>
            <ValidParenthesesVisualization />
          </Suspense>
        );
      case 21:
        return (
          <Suspense fallback={<div>Loading visualization...</div>}>
            <MergeTwoSortedListsVisualization />
          </Suspense>
        );
      default:
        return <div>No visualization available for this problem.</div>;
    }
  };
  
  return (
    <PageContainer>
      <BackButton 
        onClick={handleBack}
        whileHover={{ x: -5 }}
        whileTap={{ scale: 0.95 }}
      >
        ← Back to Questions
      </BackButton>
      
      <HeaderSection>
        <Title>{question.title}</Title>
        <Metadata>
          <Tag type={question.difficulty}>
            {question.difficulty.charAt(0).toUpperCase() + question.difficulty.slice(1)}
          </Tag>
          {question.companies.map(company => (
            <Tag key={company} type={company}>
              {company.charAt(0).toUpperCase() + company.slice(1)}
            </Tag>
          ))}
          {question.topics.map(topic => (
            <Tag key={topic} type="topic">
              {topic.charAt(0).toUpperCase() + topic.slice(1)}
            </Tag>
          ))}
        </Metadata>
      </HeaderSection>
      
      <TabSection>
        <TabList>
          <Tab 
            active={activeTab === 'description'} 
            onClick={() => setActiveTab('description')}
          >
            Description
          </Tab>
          <Tab 
            active={activeTab === 'solution'} 
            onClick={() => setActiveTab('solution')}
          >
            Solution
          </Tab>
          <Tab 
            active={activeTab === 'visualization'} 
            onClick={() => setActiveTab('visualization')}
          >
            Visualization
          </Tab>
          <Tab 
            active={activeTab === 'approach'} 
            onClick={() => setActiveTab('approach')}
          >
            Approach
          </Tab>
        </TabList>
        
        <ContentSection>
          {activeTab === 'description' && (
            <>
              <SectionTitle>Problem Description</SectionTitle>
              <Description>
                {solution.description}
              </Description>
              
              {solution.examples.map((example, index) => (
                <ExampleBox key={index}>
                  <ExampleTitle>Example {index + 1}</ExampleTitle>
                  <p><strong>Input:</strong> {example.input}</p>
                  <p><strong>Output:</strong> {example.output}</p>
                  {example.explanation && <p><strong>Explanation:</strong> {example.explanation}</p>}
                </ExampleBox>
              ))}
            </>
          )}
          
          {activeTab === 'solution' && (
            <>
              <SectionTitle>Java Solution</SectionTitle>
              <CodeBlock className="language-java">
                {solution.code.java}
              </CodeBlock>
            </>
          )}
          
          {activeTab === 'visualization' && (
            <>
              <SectionTitle>Solution Visualization</SectionTitle>
              <VisualizationContainer>
                {getVisualizationComponent(questionId)}
              </VisualizationContainer>
            </>
          )}
          
          {activeTab === 'approach' && (
            <>
              <SectionTitle>Approach</SectionTitle>
              <Description>
                {solution.approach}
              </Description>
              
              <SectionTitle>Complexity Analysis</SectionTitle>
              <p><strong>Time Complexity:</strong> {solution.timeComplexity}</p>
              <p><strong>Space Complexity:</strong> {solution.spaceComplexity}</p>
            </>
          )}
        </ContentSection>
      </TabSection>
    </PageContainer>
  );
};

export default InterviewQuestionDetailPage; 