            <TheoryText><strong>Circular Queue Implementation:</strong></TheoryText>
            <CodeBlock>
{`public class CircularQueue<T> {
    private T[] items;
    private int capacity;
    private int currentLength;
    private int front;
    private int rear;
    
    @SuppressWarnings("unchecked")
    public CircularQueue(int capacity) {
        this.items = (T[]) new Object[capacity];
        this.capacity = capacity;
        this.currentLength = 0;
        this.front = -1;
        this.rear = -1;
    }
    
    // Check if queue is full
    public boolean isFull() {
        return this.currentLength == this.capacity;
    }
    
    // Check if queue is empty
    public boolean isEmpty() {
        return this.currentLength == 0;
    }
    
    // Add an element to the circular queue
    public void enqueue(T element) {
        if (isFull()) {
            throw new IllegalStateException("Queue is full");
        }
        
        this.rear = (this.rear + 1) % this.capacity;
        this.items[this.rear] = element;
        this.currentLength++;
        
        if (this.front == -1) {
            this.front = this.rear;
        }
    }
    
    // Remove and return the front element
    public T dequeue() {
        if (isEmpty()) {
            throw new IllegalStateException("Queue is empty");
        }
        
        T item = this.items[this.front];
        this.items[this.front] = null;
        this.front = (this.front + 1) % this.capacity;
        this.currentLength--;
        
        if (isEmpty()) {
            this.front = -1;
            this.rear = -1;
        }
        
        return item;
    }
    
    // Return the front element without removing it
    public T peek() {
        if (isEmpty()) {
            throw new IllegalStateException("Queue is empty");
        }
        
        return this.items[this.front];
    }
    
    // Get the size of the queue
    public int size() {
        return this.currentLength;
    }
    
    // Get the capacity of the queue
    public int getCapacity() {
        return this.capacity;
    }
    
    // Print the queue
    @Override
    public String toString() {
        if (isEmpty()) {
            return "[]";
        }
        
        StringBuilder result = new StringBuilder("[");
        int count = 0;
        int i = this.front;
        
        while (count < this.currentLength) {
            result.append(this.items[i]);
            if (count < this.currentLength - 1) {
                result.append(", ");
            }
            i = (i + 1) % this.capacity;
            count++;
        }
        
        result.append("]");
        return result.toString();
    }
}`}
