{`import java.util.ArrayList;
import java.util.List;

public class HashTableLinearProbing<K, V> {
    private Entry<K, V>[] keyMap;
    private int size;
    private int capacity;
    private final double loadFactor = 0.7; // Threshold for resizing
    private final Entry<K, V> DELETED = new Entry<>(null, null); // Tombstone for deleted entries
    
    @SuppressWarnings("unchecked")
    public HashTableLinearProbing(int size) {
        this.capacity = size;
        this.keyMap = (Entry<K, V>[]) new Entry[size];
        this.size = 0;
    }
    
    private int hash(K key) {
        if (key == null) {
            return 0;
        }
        
        int total = 0;
        final int WEIRD_PRIME = 31;
        String keyString = key.toString();
        
        if (key instanceof Number) {
            return Math.abs(((Number) key).intValue() % capacity);
        }
        
        for (int i = 0; i < Math.min(keyString.length(), 100); i++) {
            char c = keyString.charAt(i);
            total = (total * WEIRD_PRIME + c) % this.capacity;
        }
        
        return total;
    }
    
    public HashTableLinearProbing<K, V> set(K key, V value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        
        // Check if we need to resize
        if ((double) size / capacity > loadFactor) {
            resize();
        }
        
        int index = hash(key);
        int originalIndex = index;
        Entry<K, V> entry = new Entry<>(key, value);
        
        // If the spot is empty or it's a tombstone, put it there
        while (keyMap[index] != null && keyMap[index] != DELETED && !keyMap[index].getKey().equals(key)) {
            index = (index + 1) % capacity; // Linear probing
            
            // If we've checked all spots, the table is full
            if (index == originalIndex) {
                resize();
                return set(key, value); // Try again with the resized table
            }
        }
        
        // If the key exists, update it
        if (keyMap[index] != null && keyMap[index] != DELETED && keyMap[index].getKey().equals(key)) {
            keyMap[index].setValue(value);
            return this;
        }
        
        keyMap[index] = entry;
        size++;
        return this;
    }
    
    public V get(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        
        int index = findIndex(key);
        
        if (index == -1) {
            return null;
        }
        
        return keyMap[index].getValue();
    }
    
    private int findIndex(K key) {
        int index = hash(key);
        int originalIndex = index;
        
        while (keyMap[index] != null) {
            if (keyMap[index] != DELETED && keyMap[index].getKey().equals(key)) {
                return index;
            }
            
            index = (index + 1) % capacity;
            
            // If we've checked all spots and didn't find the key
            if (index == originalIndex) {
                break;
            }
        }
        
        return -1; // Key not found
    }
    
    public boolean delete(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        
        int index = findIndex(key);
        
        if (index == -1) {
            return false;
        }
        
        keyMap[index] = DELETED; // Mark as deleted
        size--;
        return true;
    }
    
    public List<K> keys() {
        List<K> keysList = new ArrayList<>();
        
        for (Entry<K, V> entry : keyMap) {
            if (entry != null && entry != DELETED) {
                keysList.add(entry.getKey());
            }
        }
        
        return keysList;
    }
    
    public List<V> values() {
        List<V> valuesList = new ArrayList<>();
        
        for (Entry<K, V> entry : keyMap) {
            if (entry != null && entry != DELETED) {
                valuesList.add(entry.getValue());
            }
        }
        
        return valuesList;
    }
    
    @SuppressWarnings("unchecked")
    private void resize() {
        int newCapacity = capacity * 2;
        Entry<K, V>[] oldMap = keyMap;
        keyMap = (Entry<K, V>[]) new Entry[newCapacity];
        capacity = newCapacity;
        size = 0;
        
        for (Entry<K, V> entry : oldMap) {
            if (entry != null && entry != DELETED) {
                set(entry.getKey(), entry.getValue());
            }
        }
    }
    
    // Entry class to store key-value pairs
    private static class Entry<K, V> {
        private K key;
        private V value;
        
        public Entry(K key, V value) {
            this.key = key;
            this.value = value;
        }
        
        public K getKey() {
            return key;
        }
        
        public V getValue() {
            return value;
        }
        
        public void setValue(V value) {
            this.value = value;
        }
    }
}`}
