class Graph {
  constructor(isDirected = false) {
    this.vertices = new Map();
    this.edges = new Map();
    this.isDirected = isDirected;
  }
  
  addVertex(id, x, y) {
    if (!this.vertices.has(id)) {
      this.vertices.set(id, { id, x, y });
      this.edges.set(id, new Set());
    }
    return this;
  }
  
  addEdge(fromId, toId) {
    if (!this.vertices.has(fromId) || !this.vertices.has(toId)) {
      return false;
    }
    
    this.edges.get(fromId).add(toId);
    
    if (!this.isDirected) {
      this.edges.get(toId).add(fromId);
    }
    
    return true;
  }
  
  removeVertex(id) {
    if (!this.vertices.has(id)) {
      return false;
    }
    
    // Remove all edges to this vertex
    for (const edges of this.edges.values()) {
      edges.delete(id);
    }
    
    // Remove all edges from this vertex
    this.edges.delete(id);
    
    // Remove the vertex
    this.vertices.delete(id);
    
    return true;
  }
  
  removeEdge(fromId, toId) {
    if (!this.edges.has(fromId) || !this.edges.has(toId)) {
      return false;
    }
    
    this.edges.get(fromId).delete(toId);
    
    if (!this.isDirected) {
      this.edges.get(toId).delete(fromId);
    }
    
    return true;
  }
  
  // BFS traversal
  bfs(startId) {
    if (!this.vertices.has(startId)) {
      return [];
    }
    
    const visited = new Set();
    const result = [];
    const queue = [startId];
    visited.add(startId);
    
    while (queue.length > 0) {
      const current = queue.shift();
      result.push(current);
      
      const neighbors = this.edges.get(current);
      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) {
          visited.add(neighbor);
          queue.push(neighbor);
        }
      }
    }
    
    return result;
  }
  
  // DFS traversal
  dfs(startId) {
    if (!this.vertices.has(startId)) {
      return [];
    }
    
    const visited = new Set();
    const result = [];
    
    const dfsVisit = (id) => {
      visited.add(id);
      result.push(id);
      
      const neighbors = this.edges.get(id);
      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) {
          dfsVisit(neighbor);
        }
      }
    };
    
    dfsVisit(startId);
    return result;
  }
  
  // Generate a path between vertices for visualization
  getPath(traversal) {
    const path = [];
    
    for (let i = 0; i < traversal.length - 1; i++) {
      const fromId = traversal[i];
      const toId = traversal[i + 1];
      
      if (this.edges.get(fromId).has(toId)) {
        path.push(fromId + '-' + toId);
      }
    }
    
    return path;
  }
  
  // Check if an edge exists
  hasEdge(fromId, toId) {
    return this.edges.has(fromId) && this.edges.get(fromId).has(toId);
  }
  
  // Clear the graph
  clear() {
    this.vertices.clear();
    this.edges.clear();
  }
}

